const published = $input.first().json;
if (!published.published || Number(published.chunk_count) !== 2) throw new Error('publish workflow did not persist both chunks');
return [{ json: {
  query: '步行入口',
  tenant_id: 'default',
  access_groups: ['planning'],
  decision_steps: ['step_09_spatial_layout'],
  project_types: ['urban-renewal'],
  geography: ['demo'],
  metadata_filter: { fixture: true },
  candidate_limit: 20,
  result_limit: 5,
  context_radius: 1
} }];

const result = $input.first().json;
if (!Array.isArray(result.candidates) || result.candidates.length < 1) throw new Error('hybrid recall returned no direct hit');
if (!Array.isArray(result.contexts) || result.contexts.length < 2) throw new Error('context expansion did not read adjacent source chunks');
if (!Array.isArray(result.citations) || result.citations.some((citation) => !citation.citation_id || !citation.title || !citation.page_start)) throw new Error('citation locator is incomplete');
if (result.retrieval?.rerank?.method !== 'codex-llm' || !result.retrieval.rerank.response_id) throw new Error('Codex model rerank metadata is incomplete');
return [{ json: {
  passed: true,
  candidate_count: result.candidates.length,
  context_count: result.contexts.length,
  citation_count: result.citations.length,
  fusion: result.retrieval.fusion,
  rerank: result.retrieval.rerank.method,
} }];

const allowed = $input.first().json;
if (!allowed.passed) throw new Error('allowed retrieval assertion did not pass');
return [{ json: {
  query: '步行入口',
  tenant_id: 'default',
  access_groups: ['unauthorized-audit-group'],
  decision_steps: ['step_09_spatial_layout'],
  project_types: ['urban-renewal'],
  geography: ['demo'],
  metadata_filter: { fixture: true },
  candidate_limit: 20,
  result_limit: 5,
  context_radius: 1
} }];

const result = $input.first().json;
if (!Array.isArray(result.candidates) || result.candidates.length !== 0) throw new Error('permission filter leaked direct candidates');
if (!Array.isArray(result.contexts) || result.contexts.length !== 0) throw new Error('permission filter leaked source context');
if (!Array.isArray(result.citations) || result.citations.length !== 0) throw new Error('permission filter leaked citations');
if (result.retrieval?.rerank?.method !== 'skipped-no-candidates') throw new Error('empty permission result still invoked model rerank');
return [{ json: {
  passed: true,
  permission_isolation: true,
  candidate_count: 0,
  context_count: 0,
  citation_count: 0,
  rerank: result.retrieval.rerank.method,
} }];
